     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':\n        vars['promise_count'] = str(int(vars.get('promise_count') or 0) + 1)\n        d['what_to_do_next'] = 'Recorded. Say: You will receive an email confirming this promise. Then continue.'\n    elif isinstance(d, dict):\n        d['what_to_do_next'] = 'Not recorded. Try once more; if it already failed twice for this product, say you could not record it and call add_note with reason service_error.'\n    else:\n        result['what_to_do_next'] = 'Not recorded. Try once more; if it already failed twice for this product, say you could not record it and call add_note with reason service_error.'\nexcept Exception:\n    pass\n"
