   "task_message": "Tell them how to verify the call.",
   "on_enter": {"type": "tts", "text": "You can verify this call by phoning your relationship manager or the number on brightwell.example."},
   "passthrough": true,
   "passthrough_default_transition": "__previous__",
   "excluded_nodes": ["setup", "wrong_number_prep", "deceased_prep", "third_party_prep", "identity_prep", "load_account", "account_error", "facts", "goodbye", "goodbye_short", "goodbye_deceased", "goodbye_failed", "goodbye_error", "goodbye_transfer"],
   "transitions": [{"target_node": "__previous__", "description": "always", "condition": {"operator": "always"}}]
  }
 },
 "tools": [
