       },
       "required": ["customer_id", "outcome"]
      }
     }
    }
   },
   "pre_process_code": "import json\ntry:\n    b = config.get('body')\n    if isinstance(b, dict) and vars.get('call_state') != 'transferred' and vars.get('close_outcome') in ('no_promise', 'promise', 'paid'):\n        if int(vars.get('promise_count') or 0) > 0:\n            b['outcome'] = 'promise'\n        else:\n            notes = json.loads(vars.get('notes_json') or '[]')\n            order = json.loads(vars.get('product_order') or '[]')\n            by_id = {}\n            for pid, reason in notes:\n                by_id.setdefault(pid, reason)\n            if notes and all(r == 'paid' for _, r in notes):\n                b['outcome'] = 'paid'\n            elif notes:\n                first = next((by_id[p] for p in order if p in by_id and by_id[p] != 'paid'), None)\n                if first is None:\n                    first = next(r for _, r in notes if r != 'paid')\n                b['outcome'] = 'no_promise'\n                b['reason'] = first\n    if isinstance(b, dict) and (b.get('outcome') in ('promise', 'paid') or not b.get('reason')):\n        b.pop('reason', None)\nexcept Exception:\n    pass\n"
  }
 ]
}

