     "post_process_code": "try:\n    result.pop('header', None)\n    d = result.get('data')\n    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'\n    if ok:\n        q = vars.get('transfer_queue') or 'relationship_manager'\n        vars['call_state'] = 'transferred'\n        vars['close_outcome'] = 'transferred'\n        vars['close_reason'] = {'restructuring': 'restructuring', 'support': 'support'}.get(q, 'human')\n        d['what_to_do_next'] = 'Say a colleague will take over, thank them and say goodbye, then call end_call. Add no notes.'\n    elif isinstance(d, dict):\n        d['what_to_do_next'] = 'The transfer failed. Say so and continue.'\n    else:\n        result['what_to_do_next'] = 'The transfer failed. Say so and continue.'\nexcept Exception:\n    pass\n"
