        "code": {
         "type": "string",
         "default": "import datetime\nimport json\n\nWEEKDAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']\nMONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']\nHOL = set(datetime.date.fromisoformat(x) for x in ['2026-10-19', '2026-11-11', '2026-12-24', '2026-12-25', '2026-12-31'])\nBANDS = [(1, 15, 10, 1), (16, 60, 5, 2)]\nTYPES = {'business_card': ('business card ending ', 'minimum_payment'), 'business_loan': ('business loan', 'instalment_amount'), 'overdraft': ('business overdraft', 'minimum_repayment')}\n\ndef parse_now(value):\n    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')\n    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):\n        try:\n            return datetime.datetime.strptime(s[:size], fmt)\n        except ValueError:\n            pass\n    raise ValueError('cannot read now')\n\ndef is_bd(d):\n    return d.weekday() < 5 and d not in HOL\n\ndef next_bd(d):\n    d = d + datetime.timedelta(days=1)\n    while not is_bd(d):\n        d = d + datetime.timedelta(days=1)\n    return d\n\ndef add_bd(d, n):\n    for _ in range(n):\n        d = next_bd(d)\n    return d\n\ndef last_bd_of_week(d):\n    mon = d - datetime.timedelta(days=d.weekday())\n    day = mon + datetime.timedelta(days=4)\n    while day >= mon:\n        if is_bd(day):\n            return day\n        day = day - datetime.timedelta(days=1)\n    return None\n\ndef spoken(d):\n    return WEEKDAYS[d.weekday()] + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1]\n\ndef money(v):\n    return '{:,.2f}'.format(round(float(v or 0), 2))\n\ndef as_list(value):\n    if isinstance(value, list):\n        return value\n    if isinstance(value, str):\n        try:\n            value = json.loads(value)\n        except ValueError:\n            return []\n    if isinstance(value, dict):\n        return [value]\n    return value if isinstance(value, list) else []\n\ndef list_from_vars(vars, name, prefixes):\n    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []\n    if found:\n        return found\n    for prefix in prefixes:\n        rows = {}\n        start = prefix + '.'\n        for key, value in vars.items():\n            if not str(key).startswith(start):\n                continue\n            idx, _, field = str(key)[len(start):].partition('.')\n            if idx.isdigit():\n                if field:\n                    rows.setdefault(int(idx), {})[field] = value\n                else:\n                    rows[int(idx)] = value\n        if rows:\n            return [rows[i] for i in sorted(rows)]\n        whole = vars.get(prefix)\n        if whole not in (None, ''):\n            got = as_list(whole)\n            if got:\n                return got\n    return []\n\ntry:\n    now = parse_now(vars.get('now'))\n    today = now.date()\n    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])\n    statements, lines, order = [], [], []\n    max_dl = today\n    week_end = last_bd_of_week(today)\n    if week_end is None or week_end <= today:\n        week_end = last_bd_of_week(today + datetime.timedelta(days=7))\n    for n, it in enumerate(items, 1):\n        typ = str(it.get('type') or '')\n        label, floor_field = TYPES.get(typ, ('product', 'minimum_payment'))\n        name = label + str(it.get('card_last4') or '') if typ == 'business_card' else label\n        days = int(float(it.get('days_late') or 0))\n        band = next((b for b in BANDS if b[0] <= days <= b[1]), BANDS[-1])\n        deadline = add_bd(today, band[2])\n        max_dl = max(max_dl, deadline)\n        a1 = min(week_end, deadline) if week_end else deadline\n        past_due = float(it.get('past_due') or 0)\n        floor = float(it.get(floor_field) or 0)\n        pid = str(it.get('product_id'))\n        order.append(pid)\n        statements.append('Your ' + name + ' has ' + money(past_due) + ' past due and is ' + str(days) + ' days late.')\n        l = (str(n) + '. ' + name + ' (product_id ' + pid + '): past due ' + money(past_due) + ', ' + str(days) + ' days late. Floor (lowest amount): ' + money(floor) +\n             '. Deadline (latest date): ' + spoken(deadline) + ' (' + deadline.isoformat() + '). Persuasion attempts allowed: ' + str(band[3]) + '.\\n' +\n             '   Attempt 1 (say exactly): \"For your ' + name + ', could you pay ' + money(past_due) + ' on ' + spoken(a1) + '?\" (amount ' + str(past_due) + ', date ' + a1.isoformat() + ')\\n' +\n             '   Attempt 1 if the customer already said the full amount is too much (say exactly): \"For your ' + name + ', could you pay ' + money(floor) + ' on ' + spoken(a1) + '? The rest stays overdue.\" (amount ' + str(floor) + ', date ' + a1.isoformat() + ')\\n' +\n             '   Full amount too much (say exactly, once): \"The lowest amount I can record for your ' + name + ' is ' + money(floor) + '. The rest stays overdue.\"\\n' +\n             '   Date after the deadline (say exactly): \"The latest date I can record for your ' + name + ' is ' + spoken(deadline) + '.\"')\n        if band[3] >= 2:\n            l += '\\n   Attempt 2 (say exactly): \"For your ' + name + ', could you pay ' + money(floor) + ' on ' + spoken(deadline) + '? The rest stays overdue.\" (amount ' + str(floor) + ', date ' + deadline.isoformat() + ')'\n        else:\n            l += '\\n   No attempt 2 for this product: after one refused attempt, the product ends without a promise.'\n        lines.append(l)\n    cal, d = [], today\n    while d <= max_dl:\n        cal.append(spoken(d) + ' ' + d.isoformat() + (' business day' if is_bd(d) else ' NOT a business day'))\n        d = d + datetime.timedelta(days=1)\n    first_ask = 'Can you make this payment today?' if len(items) <= 1 else 'Can you make this payment today, for all of them?'\n    vars['statement_text'] = 'Thank you. I am calling from the collections team about a late payment. ' + ' '.join(statements) + ' ' + first_ask\n    vars['facts_text'] = ('Today is ' + spoken(today) + ' (' + today.isoformat() + '). Weeks run Monday to Sunday. \"Next <weekday>\" is that weekday in the following calendar week; \"this <weekday>\" is the one in the current week.\\nCalendar:\\n' + '\\n'.join(cal) +\n                          '\\n\\nProducts, in this order:\\n' + '\\n'.join(lines))\n    vars['product_order'] = json.dumps(order)\n    vars['product_count'] = str(len(items))\n    vars['facts_state'] = 'ok' if items else 'empty'\n    vars['close_outcome'] = 'no_promise'\n    vars['close_reason'] = 'refused' if items else 'service_error'\nexcept Exception:\n    vars['statement_text'] = 'Thank you. I am calling from the collections team about a late payment.'\n    vars['facts_text'] = 'The account details could not be read.'\n    vars['product_count'] = '0'\n    vars['facts_state'] = 'error'\n    vars['close_outcome'] = 'no_promise'\n    vars['close_reason'] = 'service_error'\n"
